{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_aborted",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.attr_status_code cstat, s.service_name callee, s.attr_status_code sstat, s.attr_http_response_status_code scode, count(*) n, round(avg(c.duration/1e6),1) c_ms, round(avg(s.duration/1e6),1) s_ms, round(min(s.duration/1e6),1) s_min, round(max(s.duration/1e6),1) s_max FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Client' GROUP BY ALL ORDER BY n DESC",
          "claim": "Travel-plan's outgoing calls to route-plan fail with Error (572) while route-plan's server spans return 200 in about 362 ms."
        },
        {
          "kind": "log",
          "sql": "SELECT * FROM abnormal_logs WHERE service_name='ts-travel-plan-service' AND level='SEVERE' LIMIT 1",
          "claim": "Travel-plan logs SEVERE ResourceAccessException 'Connection reset' on POST to ts-route-plan-service routePlan endpoint."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind kind, attr_status_code, attr_http_response_status_code code, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND span_name LIKE '%minStation%' GROUP BY 1,2,3,4",
          "claim": "Travel-plan minStation server spans return HTTP 500 with Error status (572), unlike the normal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p, span_name, attr_span_kind kind, n, med_ms, p95_ms, err FROM (SELECT 'abn' p, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration/1e6,0.5),1) med_ms, round(quantile_cont(duration/1e6,0.95),1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) err FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind IN ('Server','Client') GROUP BY 1,2,3 UNION ALL SELECT 'nor', span_name, attr_span_kind, count(*), round(quantile_cont(duration/1e6,0.5),1), round(quantile_cont(duration/1e6,0.95),1), sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind IN ('Server','Client') GROUP BY 1,2,3) ORDER BY span_name, p",
          "claim": "User-facing ui-dashboard minStation requests show 27 errors and median 6.8s, versus 0 errors and 0.7s normally."
        }
      ]
    }
  ]
}
